const express=require('express'),router=express.Router(),challengeController=require('../controllers/challengesController.min.js'),{onlyAdminAuth}=require('../middlewares/auth.min.js'),cache=require('../route_cache.js'),TWELVE_HOURS=43200;router.post('/challenges',onlyAdminAuth,challengeController.create_challenge);router.get('/challenges',cache(TWELVE_HOURS),challengeController.get_challenges);router.get('/admin-challenges',onlyAdminAuth,challengeController.get_admin_challenges);router.get('/challenges/:id',onlyAdminAuth,challengeController.get_single_challenge);router.delete('/challenges/:id',onlyAdminAuth,challengeController.delete_challenge);router.put('/challenges/:id',onlyAdminAuth,challengeController.update_challenge);module.exports=router; 